// Email Form Component
'use client'
import { useState } from 'react';
import Head from 'next/head';
import type { NextApiRequest, NextApiResponse } from 'next';

export function Interest(req: NextApiRequest, res: NextApiResponse) {
  const mailjet = require ('node-mailjet')
  const mailjetClient = mailjet.connect(
    process.env.MJ_APIKEY_PUBLIC!,
    process.env.MJ_APIKEY_PRIVATE!
  );
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [submitted, setSubmitted] = useState(false);
  
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // if (!email || !message) return;

  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { email: reqEmail, message: reqMessage } = req.body;

  if (!reqEmail || !reqMessage) {
    return res.status(400).json({ error: 'Email and message are required' });
  }

  try {
    const request = mailjetClient.post('send', { version: 'v3.1' }).request({
      Messages: [
        {
          From: {
            Email: 'manolis277@gmail.com', // Replace with your sender email
            Name: 'Manolis',
          },
          To: [
            {
              email,
              Name: 'Manolis',
            },
          ],
          Subject: 'New Message from Your Website',
          TextPart: message,
          HTMLPart: `<p>${message}</p>`,
        },
      ],
    });

    await request;
    res.status(200).json({ success: true });
  } catch (error) {
    console.error('Mailjet error:', error);
    res.status(500).json({ error: 'Failed to send email' });
  }
}


  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-070F2B">
    <Head>
      <title>Email me</title>
    </Head>
    <div className="max-w-md w-full text-center bg-white shadow-lg p-8 rounded-2xl">
      <h1 className="text-indigo-950 text-3xl font-bold mb-4">Say hi!</h1>
      {!submitted ? (
      <p className="text-indigo-950 mb-6">
        Let's get in touch
      </p>
      ) : (
      <p className="text-purple-600 font-semibold">
        Thanks for reaching out! 🎉<br /> I will get back to you soon.
      </p>
      )}
      {!submitted && (
      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <input
        type="email"
        placeholder="Your email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        required
        className="p-3 border rounded-lg text-black"
        />
        <textarea
        placeholder="Your message"
        value={message}
        onChange={(e) => setMessage(e.target.value)}
        required
        className="p-3 border rounded-lg text-black"
        rows={4}
        />
        <button
        type="submit"
        className="bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700"
        >
        Send Message
        </button>
      </form>
      )}
    </div>
    </div>
  );
  }